class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        cnt = [0] * 32
        ans = float('inf')
        left = 0
        cur = 0
        for right in range(n):
            x = nums[right]
            for b in range(32):
                if x >> b & 1:
                    cnt[b] += 1
                    cur |= 1 << b
            while cur >= k and left <= right:
                ans = min(ans, right - left + 1)
                y = nums[left]
                for b in range(32):
                    if y >> b & 1:
                        cnt[b] -= 1
                        if cnt[b] == 0:
                            cur ^= 1 << b
                left += 1
        return ans if ans != float('inf') else -1

