class Solution {
public:
    int minimumSubarrayLength(vector<int>& nums, int k) {
        int n = nums.size(), ans = INT_MAX, left = 0, cur = 0;
        vector<int> cnt(32, 0);
        for (int right = 0; right < n; right++) {
            for (int b = 0; b < 32; b++)
                if (nums[right] >> b & 1) { cnt[b]++; cur |= 1 << b; }
            while (cur >= k && left <= right) {
                ans = min(ans, right - left + 1);
                for (int b = 0; b < 32; b++)
                    if (nums[left] >> b & 1 && --cnt[b] == 0) cur ^= 1 << b;
                left++;
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

